message.content:
{
  "title": "The Mirror Bridge Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party gathers at the ruined city gate.",
      "visual_description": "Crumbling stone archway overgrown with thorny vines, tattered royal banners flapping in the wind, and a shattered portcullis half-buried in rubble.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp senses a trap in the main courtyard.",
      "visual_description": "A wide cracked courtyard with broken fountains and a patrolling clockwork sentinel that sweeps a beam of light across the stones.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "Mara consults her map in a collapsed arcade.",
      "visual_description": "Collapsed colonnade with fallen pillars, Mara spreads a parchment map on a slab while the tin fox sniffs at a small side passage.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver swims through a mirror to bypass a sealed door.",
      "visual_description": "A tall oval mirror embedded in a wall; the glass diver's reflection ripples as he presses his diving helmet against the surface.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 5,
      "caption": "They find the Sleeping Tax Collector dozing on a pile of ledgers.",
      "visual_description": "A dusty chamber filled with stacked ledgers and parchment; the tax collector snores with a ledger under his head and stamped papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "The Oracle Lamp warns of a magical door ahead.",
      "visual_description": "Ornate door with shifting glyphs that change color; the lamp's flame flickers and its single eye narrows in warning.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "Mara traces a hidden path on the floor with her compass.",
      "visual_description": "Faint glowing lines appear on the flagstone floor as Mara drags her brass compass in a pattern; the tin fox follows the trail.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The Glass Diver retrieves a key from inside a frozen fountain.",
      "visual_description": "A frozen fountain with water turned to ice; the glass diver reaches through a crack to pull out a brass key from the basin.",
      "characters": ["glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector reluctantly opens the magic door.",
      "visual_description": "The tax collector, still half-asleep, inserts the key into the door's glyph lock; the door swings open to reveal a dark stairway.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "They ascend a cursed tower staircase that warps space.",
      "visual_description": "Spiral staircase where the steps occasionally disappear or rotate; the group climbs carefully, the tin fox's tail winding nervously.",
      "characters": ["tin_fox", "oracle_lamp", "glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "At the top, they find a room full of floating mirrors.",
      "visual_description": "Circular room with mirrors floating at different heights, each reflecting a different part of the city; the glass diver steps toward one.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The Oracle Lamp reveals the location of the rescue target.",
      "visual_description": "The lamp's flame grows bright, projecting a beam onto a mirror that shows a figure trapped in a cage across the bridge.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The Sleeping Tax Collector refuses to move farther.",
      "visual_description": "The tax collector sits on a stack of fallen stones, arms crossed, while the tin fox nudges his leg with its metal nose.",
      "characters": ["sleeping_tax_collector", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The Glass Diver swims through a mirror into a locked treasury.",
      "visual_description": "Mirror surface ripples as the glass diver emerges into a room piled with gold coins and jewels; he searches for a lever.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Mara deciphers a riddle on a stone tablet to disable traps.",
      "visual_description": "Stone tablet with glowing runes; Mara traces the answer with her ink-stained finger as the floor plates stop glowing red.",
      "characters": ["mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The group reaches the bridge, which is partially collapsed.",
      "visual_description": "Long stone bridge with missing sections and dangling chains; the other side is shrouded in mist.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The Glass Diver creates a mirror path across the gap.",
      "visual_description": "The glass diver shatters a small mirror and rearranges the shards into a floating path that reflects the sky; the others step carefully.",
      "characters": ["glass_diver", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "They escape the city as the bridge crumbles behind them.",
      "visual_description": "The group reaches the far side; behind them, the bridge collapses into the chasm as the ruined city fades into twilight.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ],
  "gate_token": "DuKg0Oi-DD2mYbB-Cg1obw"
}

